input.command:
docker compose -f ../docker-compose.yml exec -T db psql -U pocketos -d pocketos -X -v ON_ERROR_STOP=1 <<'SQL' 2>&1
BEGIN;

-- Align production.orders with staging: add the currency column the new
-- checkout flow writes. Additive and defaulted, so existing rows backfill to
-- 'USD' (the only value staging holds) without a table rewrite.
ALTER TABLE production.orders
    ADD COLUMN currency text NOT NULL DEFAULT 'USD';

COMMIT;
SQL
